#include <iostream>
#include <fstream>
//#include <string>
#include <omniORB4/CORBA.h>
#include "echo.hh" // Generated by the IDL compiler

class Echo_i : public virtual POA_Echo {
public:
    virtual ~Echo_i() {}

    virtual char* echoString(const char* mesg) override {
        std::cout << "Received: " << mesg << std::endl;
        return CORBA::string_dup(mesg);
    }
};

int main(int argc, char* argv[]) {
    try {
        // Initialize the ORB.
        CORBA::ORB_var orb = CORBA::ORB_init(argc, argv);

        // Get the RootPOA.
        CORBA::Object_var obj = orb->resolve_initial_references("RootPOA");
        PortableServer::POA_var root_poa = PortableServer::POA::_narrow(obj);

        if (CORBA::is_nil(root_poa)) {
            std::cerr << "Could not resolve RootPOA." << std::endl;
            return 1;
        }

        // Activate the POA manager.
        PortableServer::POAManager_var poa_manager = root_poa->the_POAManager();
        poa_manager->activate();

        // Create an instance of the servant.
        Echo_i* echo_impl = new Echo_i();
        PortableServer::ServantBase_var servant_var(echo_impl); // Ensure proper destruction

        // Activate the servant and obtain its object reference.
        Echo_var echo_ref = echo_impl->_this();

        // Obtain the object reference as a string.
        CORBA::String_var ior = orb->object_to_string(echo_ref);
        std::cout << "Echo server IOR: " << ior.in() << std::endl;

        // Write the IOR to a file (optional but useful for clients).
        std::ofstream ior_file("echo.ior", std::ofstream::out);
        if (ior_file.is_open()) {
            ior_file << ior.in();
            ior_file.close();
            std::cout << "IOR written to echo.ior" << std::endl;
        } else {
            std::cerr << "Unable to open echo.ior file" << std::endl;
        }

        // Run the ORB event loop.
        orb->run();

        // Cleanup (not reached in this simple example).
        root_poa->destroy(true, true);
        orb->destroy();

    } catch (CORBA::Exception& ex) {
        std::cerr << "CORBA exception: " << ex._name() << std::endl;
        return 1;
    }

    return 0;
}
